package com.retail.inventory.service;
import com.retail.inventory.dto.request.*;import com.retail.inventory.entity.*;import com.retail.inventory.entity.enums.*;import com.retail.inventory.exception.*;import com.retail.inventory.repository.*;import com.retail.inventory.service.impl.OrderServiceImpl;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import java.math.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class OrderServiceImplTest { @Mock OrderRepository orders;@Mock ProductRepository products;@Mock WarehouseRepository warehouses;@Mock SupplierRepository suppliers;@Mock InventoryRepository inventory;@Mock StockTransactionRepository transactions;@InjectMocks OrderServiceImpl service;
 @Test void createsMultipleItemsAndCalculatesTotal(){Warehouse w=warehouse();Product a=product(1L,"A"),b=product(2L,"B");when(warehouses.findById(1L)).thenReturn(Optional.of(w));when(products.findById(1L)).thenReturn(Optional.of(a));when(products.findById(2L)).thenReturn(Optional.of(b));when(orders.save(any())).thenAnswer(x->{Order o=x.getArgument(0);o.setId(1L);return o;});var r=service.create(CreateOrderRequest.builder().orderType(OrderType.SALES_ORDER).warehouseId(1L).taxAmount(new BigDecimal("2")).shippingAmount(new BigDecimal("3")).items(List.of(item(1,2,"10"),item(2,1,"5"))).build());assertEquals(new BigDecimal("30"),r.getTotalAmount());assertEquals(2,r.getItems().size());}
 @Test void rejectsDuplicateItemsAndInvalidTransition(){when(warehouses.findById(1L)).thenReturn(Optional.of(warehouse()));when(products.findById(1L)).thenReturn(Optional.of(product(1L,"A")));assertThrows(BadRequestException.class,()->service.create(CreateOrderRequest.builder().orderType(OrderType.SALES_ORDER).warehouseId(1L).items(List.of(item(1,1,"1"),item(1,1,"1"))).build()));Order o=new Order();o.setId(1L);o.setStatus(OrderStatus.DRAFT);o.setOrderType(OrderType.SALES_ORDER);o.setWarehouse(warehouse());when(orders.findByIdWithDetails(1L)).thenReturn(Optional.of(o));assertThrows(BadRequestException.class,()->service.updateStatus(1L,OrderStatusUpdateRequest.builder().status(OrderStatus.SHIPPED).build()));}
 @Test void rejectsInsufficientAndRepeatedCancellation(){Order o=new Order();o.setId(1L);o.setStatus(OrderStatus.CANCELLED);o.setOrderType(OrderType.SALES_ORDER);o.setWarehouse(warehouse());when(orders.findByIdWithDetails(1L)).thenReturn(Optional.of(o));assertThrows(BadRequestException.class,()->service.cancel(1L));}
 private Warehouse warehouse(){Warehouse w=new Warehouse();w.setId(1L);w.setWarehouseCode("WH");return w;}private Product product(Long id,String s){Product p=new Product();p.setId(id);p.setSku(s);p.setName(s);return p;}private OrderItemRequest item(long id,int q,String price){return OrderItemRequest.builder().productId(id).quantity(q).unitPrice(new BigDecimal(price)).build();}}
